import java.util.*;

public class Main {
    public static void main(String[] args) {

        // Word frequency counter — try adding more words!
        String sentence = "to be or not to be that is the question to be";
        String[] words = sentence.split(" ");

        Map<String, Integer> freq = new HashMap<>();
        for (String word : words)
            freq.merge(word, 1, Integer::sum);

        System.out.println("Frequency map: " + freq);

        // Sort by frequency descending
        System.out.println("\nSorted by frequency:");
        freq.entrySet().stream()
            .sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
            .forEach(e -> System.out.println("  '" + e.getKey() + "' appears " + e.getValue() + " time(s)"));

        System.out.println("\nMost frequent: " +
            freq.entrySet().stream()
                .max(Map.Entry.comparingByValue())
                .map(Map.Entry::getKey).orElse("none"));
    }
}

